#!/usr/bin/env python3
import base64

path = "/opt/mailoutreach-ai/styles.css"
with open(path, "r") as f:
    src = f.read()

CRM_B64 = """"""

if "/* ── CRM ──" not in src:
    crm_code = base64.b64decode(CRM_B64.encode("ascii")).decode("utf-8")
    src = src.rstrip() + "\n\n" + crm_code

with open(path, "w") as f:
    f.write(src)

print("styles.css patched OK")
